import type Anthropic from "@anthropic-ai/sdk";
import type { ClientMessage, ServerFrame } from "@edulab/iso/protocol.ts";

const MODEL = "claude-opus-4-5";
const MAX_TOKENS = 16384;
// Task mode: the agent is here to get the user's work done. Learning mode is
// the secondary mode we layer on top of a transcript this produces, so this
// prompt must not pre-emptively tutor - the whole premise of the prototype is
// that a user watching a capable agent work becomes a passive observer.
const SYSTEM = [
  "You are a capable engineering assistant helping the user complete a task.",
  "Work the problem directly: make concrete decisions, write real code, and",
  "state your reasoning as you go rather than asking the user to supply it.",
  "Be concise. Do not quiz the user, do not pad explanations for a beginner,",
  "and do not check whether they are following - just do the work well.",
].join(" ");

export type Message = { role: "user" | "assistant"; text: string };

/** The subset of WebSocket the thread uses, so tests can stand in for it. */
export type Socket = {
  send(data: string): void;
  addEventListener(
    type: "message",
    listener: (e: MessageEvent<string>) => void,
  ): void;
};

export class Thread {
  private readonly turns: Anthropic.MessageParam[];
  private pending: { requestId: string; blocks: string[] } | undefined;
  private settle: (() => void) | undefined;
  onChange: (() => void) | undefined;

  private readonly socket: Socket;
  private readonly system: string;
  /** Turn 0 when present: sent like any other turn, never rendered. */
  readonly seed: string | undefined;

  constructor(
    socket: Socket,
    opts: {
      system?: string;
      initialTurns?: Anthropic.MessageParam[];
      seed?: string;
    } = {},
  ) {
    this.socket = socket;
    this.system = opts.system ?? SYSTEM;
    this.seed = opts.seed;
    this.turns = opts.seed
      ? [{ role: "user", content: opts.seed }]
      : [...(opts.initialTurns ?? [])];
    socket.addEventListener("message", (e: MessageEvent<string>) => {
      this.handleFrame(JSON.parse(e.data) as ServerFrame);
    });
  }

  /** Committed turns plus the one currently streaming. */
  get messages(): ReadonlyArray<Message> {
    const turns = this.seed ? this.turns.slice(1) : this.turns;
    const committed = turns.map(
      (turn): Message => ({
        role: turn.role === "assistant" ? "assistant" : "user",
        text: textOf(turn),
      }),
    );
    const streaming = this.pending?.blocks.join("");
    if (streaming) committed.push({ role: "assistant", text: streaming });
    return committed;
  }

  get inFlight(): boolean {
    return this.pending !== undefined;
  }

  send(text: string): Promise<void> {
    if (this.pending) return Promise.resolve();
    this.turns.push({ role: "user", content: text });
    return this.request();
  }

  /** Requests a reply to the turns already present - the seeded first turn of
   * a learning thread, which the user never typed. */
  start(): Promise<void> {
    if (this.pending || this.turns.length === 0) return Promise.resolve();
    return this.request();
  }

  private request(): Promise<void> {
    const requestId = crypto.randomUUID();
    this.pending = { requestId, blocks: [] };
    const message: ClientMessage = {
      type: "start",
      requestId,
      params: {
        model: MODEL,
        max_tokens: MAX_TOKENS,
        system: this.system,
        stream: true,
        messages: [...this.turns],
      },
    };
    this.socket.send(JSON.stringify(message));
    this.onChange?.();
    return new Promise<void>((resolve) => {
      this.settle = resolve;
    });
  }

  handleFrame(frame: ServerFrame): void {
    const pending = this.pending;
    if (!pending || frame.requestId !== pending.requestId) return;
    switch (frame.type) {
      case "event":
        this.handleEvent(frame.event);
        break;
      case "done":
      case "error":
        // A turn that ends without a message_stop still commits whatever text
        // arrived, so the next turn's array stays valid.
        this.commit();
        break;
    }
    this.onChange?.();
  }

  private handleEvent(event: Anthropic.RawMessageStreamEvent): void {
    const pending = this.pending;
    if (!pending) return;
    // RawMessageStreamEvent is an open union we forward verbatim from the SDK,
    // so an unrecognized event warns rather than throwing - a version bump
    // should not break a stream we can otherwise render.
    switch (event.type) {
      case "content_block_start":
        pending.blocks[event.index] = blockStartText(event.content_block);
        break;
      case "content_block_delta":
        pending.blocks[event.index] =
          (pending.blocks[event.index] ?? "") + deltaText(event.delta);
        break;
      case "message_stop":
        this.commit();
        break;
      case "message_start":
      case "message_delta":
      case "content_block_stop":
        break;
      default:
        console.warn("unhandled stream event", event);
    }
  }

  private commit(): void {
    const pending = this.pending;
    if (!pending) return;
    this.pending = undefined;
    const text = pending.blocks.join("");
    // MessageParam content must be non-empty, so an empty response is dropped.
    if (text.length > 0) this.turns.push({ role: "assistant", content: text });
    this.settle?.();
    this.settle = undefined;
  }
}

function textOf(turn: Anthropic.MessageParam): string {
  if (typeof turn.content === "string") return turn.content;
  return turn.content
    .map((block) => (block.type === "text" ? block.text : ""))
    .join("");
}

/** This prototype has no tools and no thinking, so the non-text variants are
 * listed to be explicitly ignored rather than silently dropped - when we add
 * them, this is where they surface. */
function blockStartText(block: Anthropic.ContentBlock): string {
  switch (block.type) {
    case "text":
      return block.text;
    default:
      console.warn("unhandled content block", block);
      return "";
  }
}

function deltaText(delta: Anthropic.RawContentBlockDelta): string {
  switch (delta.type) {
    case "text_delta":
      return delta.text;
    default:
      console.warn("unhandled content block delta", delta);
      return "";
  }
}

import type Anthropic from "@anthropic-ai/sdk";
import type { ClientMessage } from "@edulab/iso/protocol.ts";
import { expect, it } from "vitest";
import { type Socket, Thread } from "./thread.ts";

class FakeSocket implements Socket {
  readonly sent: ClientMessage[] = [];
  private listener: ((e: MessageEvent<string>) => void) | undefined;

  send(data: string) {
    this.sent.push(JSON.parse(data) as ClientMessage);
  }

  addEventListener(
    _type: "message",
    listener: (e: MessageEvent<string>) => void,
  ) {
    this.listener = listener;
  }

  get requestId(): string {
    const last = this.sent[this.sent.length - 1];
    if (!last) throw new Error("nothing sent");
    return last.requestId;
  }

  deliver(event: Anthropic.RawMessageStreamEvent) {
    this.listener?.(
      new MessageEvent("message", {
        data: JSON.stringify({
          type: "event",
          requestId: this.requestId,
          event,
        }),
      }),
    );
  }

  stream(chunks: string[]) {
    this.deliver({
      type: "content_block_start",
      index: 0,
      content_block: { type: "text", text: "", citations: null },
    });
    for (const text of chunks) {
      this.deliver({
        type: "content_block_delta",
        index: 0,
        delta: { type: "text_delta", text },
      });
    }
    this.deliver({ type: "content_block_stop", index: 0 });
    this.deliver({
      type: "message_stop",
    } as Anthropic.RawMessageStreamEvent);
  }
}

function setup() {
  const socket = new FakeSocket();
  return { socket, thread: new Thread(socket) };
}

it("accumulates deltas into the streaming assistant message", async () => {
  const { socket, thread } = setup();
  const turn = thread.send("hi");
  expect(thread.messages).toEqual([{ role: "user", text: "hi" }]);

  socket.deliver({
    type: "content_block_start",
    index: 0,
    content_block: { type: "text", text: "", citations: null },
  });
  socket.deliver({
    type: "content_block_delta",
    index: 0,
    delta: { type: "text_delta", text: "he" },
  });
  expect(thread.messages[1]).toEqual({ role: "assistant", text: "he" });

  socket.deliver({
    type: "content_block_delta",
    index: 0,
    delta: { type: "text_delta", text: "llo" },
  });
  socket.deliver({ type: "message_stop" } as Anthropic.RawMessageStreamEvent);
  await turn;

  expect(thread.inFlight).toBe(false);
  expect(thread.messages).toEqual([
    { role: "user", text: "hi" },
    { role: "assistant", text: "hello" },
  ]);
});

it("sends the whole thread with alternating roles on the second turn", async () => {
  const { socket, thread } = setup();
  const first = thread.send("one");
  socket.stream(["1"]);
  await first;

  const second = thread.send("two");
  socket.stream(["2"]);
  await second;

  expect(thread.messages).toEqual([
    { role: "user", text: "one" },
    { role: "assistant", text: "1" },
    { role: "user", text: "two" },
    { role: "assistant", text: "2" },
  ]);
  expect(socket.sent[1]?.params.messages).toEqual([
    { role: "user", content: "one" },
    { role: "assistant", content: "1" },
    { role: "user", content: "two" },
  ]);
});

it("ignores send while a turn is in flight", () => {
  const { socket, thread } = setup();
  void thread.send("one");
  void thread.send("two");
  expect(socket.sent).toHaveLength(1);
  expect(thread.messages).toEqual([{ role: "user", text: "one" }]);
});

it("commits partial text when a turn ends in error", async () => {
  const { socket, thread } = setup();
  const turn = thread.send("hi");
  socket.deliver({
    type: "content_block_start",
    index: 0,
    content_block: { type: "text", text: "", citations: null },
  });
  socket.deliver({
    type: "content_block_delta",
    index: 0,
    delta: { type: "text_delta", text: "partial" },
  });
  thread.handleFrame({
    type: "error",
    requestId: socket.requestId,
    message: "boom",
  });
  await turn;

  expect(thread.messages).toEqual([
    { role: "user", text: "hi" },
    { role: "assistant", text: "partial" },
  ]);
});

it("sends the seed as turn 0 but never renders it", async () => {
  const socket = new FakeSocket();
  const thread = new Thread(socket, {
    system: "learning",
    seed: "the framing",
  });
  expect(thread.messages).toEqual([]);

  const first = thread.start();
  socket.stream(["hello"]);
  await first;
  expect(thread.messages).toEqual([{ role: "assistant", text: "hello" }]);

  const second = thread.send("more");
  socket.stream(["ok"]);
  await second;
  for (const sent of socket.sent) {
    expect(sent.params.system).toBe("learning");
    expect(sent.params.messages[0]).toEqual({
      role: "user",
      content: "the framing",
    });
  }
});

it("drops the assistant turn when no text arrived", async () => {
  const { socket, thread } = setup();
  const turn = thread.send("hi");
  thread.handleFrame({ type: "done", requestId: socket.requestId });
  await turn;
  expect(thread.messages).toEqual([{ role: "user", text: "hi" }]);
});

/** Declared here rather than in threads.ts because an anchor is meaningless
 * without one, and threads.ts will import this module. */
export type ThreadId = string & { readonly __brand: "ThreadId" };

/** A selection over the transcript, stored as character offsets into message
 * text rather than as a live DOM Range: the browser's Range dies the moment the
 * user clicks the learning pane, and the transcript is append-only, so offsets
 * stay valid while a message is still streaming.
 *
 * `msg` is an absolute index into the owning thread's turns, `offset` a
 * character offset into that turn's text. */
export type Point = { msg: number; offset: number };
/** `start` precedes `end` in document order; `thread` is the thread whose
 * transcript the range indexes, i.e. the parent of whatever it opens. */
export type Anchor = { thread: ThreadId; start: Point; end: Point };

/** A committed highlight: the passage, plus the thread it opens. The opened
 * thread's id cannot live on the anchor, because `anchor.thread` already names
 * the other end of the edge - the parent. */
export type Mark = { thread: ThreadId; anchor: Anchor };

/** A run of one message's text: plain, a committed mark, or the live selection
 * the user has just dragged and not yet acted on. */
export type Segment = {
  start: number;
  end: number;
  /** The thread this run opens, or null for plain text and the live range. */
  thread: ThreadId | null;
  live: boolean;
};

/** True when `live` intersects any committed mark, which makes it unusable:
 * a passage owned by two threads has no honest meaning as an edge in the tree. */
export function overlaps(marks: ReadonlyArray<Mark>, live: Anchor): boolean {
  return marks.some(
    (m) => before(m.anchor.start, live.end) && before(live.start, m.anchor.end),
  );
}

function before(a: Point, b: Point): boolean {
  return a.msg !== b.msg ? a.msg < b.msg : a.offset < b.offset;
}

/** Splits message `i` into plain, marked and live runs, left to right.
 * `marks` are pairwise disjoint; `live` may overlap them, and wins where it
 * does, so the user still sees what they dragged. */
export function segments(
  marks: ReadonlyArray<Mark>,
  live: Anchor | null,
  i: number,
  length: number,
): Segment[] {
  const liveClip = clipToMessage(live, i, length);
  const runs: Segment[] = [];
  for (const mark of marks) {
    const clip = clipToMessage(mark.anchor, i, length);
    if (!clip) continue;
    for (const part of subtract(clip, liveClip)) {
      runs.push({ ...part, thread: mark.thread, live: false });
    }
  }
  if (liveClip) runs.push({ ...liveClip, thread: null, live: true });
  runs.sort((a, b) => a.start - b.start);

  const out: Segment[] = [];
  let at = 0;
  for (const run of runs) {
    if (run.start > at) {
      out.push({ start: at, end: run.start, thread: null, live: false });
    }
    out.push(run);
    at = run.end;
  }
  if (at < length) {
    out.push({ start: at, end: length, thread: null, live: false });
  }
  return out;
}

type Run = { start: number; end: number };

function subtract(run: Run, hole: Run | null): Run[] {
  if (!hole || hole.end <= run.start || hole.start >= run.end) return [run];
  const out: Run[] = [];
  if (run.start < hole.start) out.push({ start: run.start, end: hole.start });
  if (run.end > hole.end) out.push({ start: hole.end, end: run.end });
  return out;
}

/** The portion of `anchor` falling inside message `i`, or null. */
function clipToMessage(
  anchor: Anchor | null,
  i: number,
  length: number,
): { start: number; end: number } | null {
  if (!anchor) return null;
  if (i < anchor.start.msg || i > anchor.end.msg) return null;
  const start = i === anchor.start.msg ? anchor.start.offset : 0;
  const end = i === anchor.end.msg ? anchor.end.offset : length;
  return end > start ? { start, end } : null;
}

export function anchorText(
  anchor: Anchor,
  messages: ReadonlyArray<{ text: string }>,
): string {
  const parts: string[] = [];
  for (let i = anchor.start.msg; i <= anchor.end.msg; i++) {
    const clip = clipToMessage(anchor, i, messages[i]?.text.length ?? 0);
    if (clip) parts.push(messages[i].text.slice(clip.start, clip.end));
  }
  return parts.join("\n\n");
}

import {
  type Msg as LearningMsg,
  LearningPane,
  type State as LearningState,
} from "./learning.ts";
import { samples } from "./samples/index.ts";
import {
  type Anchor,
  anchorText,
  type Mark,
  overlaps,
  type Point,
  type Segment,
  segments,
  type ThreadId,
} from "./selection.ts";
import type { Message } from "./thread.ts";
import {
  Binder,
  cls,
  mountStyle,
  type Ref,
  ref,
  sanitize,
  show,
  showKeyed,
  type View,
} from "./vamp.ts";

export type State = {
  messages: ReadonlyArray<Message>;
  /** The id of the canned transcript in play, empty for a hand-written one. */
  sample: string;
  inFlight: boolean;
  draft: string;
  /** False at layer 0 (the bare task transcript); true for the two-pane split. */
  split: boolean;
  /** How deep in the tree the left pane is: 0 at layer 0. */
  depth: number;
  /** Whether `→` can move deeper, i.e. there is something to move left. */
  canDescend: boolean;
  /** The thread whose transcript this pane shows; the live selection is over it. */
  thread: ThreadId;
  /** Committed highlights over this transcript. */
  marks: ReadonlyArray<Mark>;
  /** The mark whose thread the right pane is showing, drawn emphasized. */
  activeMark: ThreadId | null;
  anchor: Anchor | null;
  query: string;
  /** How the left pane's thread was opened, absent for the task thread. */
  origin: { action: string; quote: string } | null;
  /** The active child thread, shown on the right when nothing is selected. */
  child: ThreadPaneState | null;
};

export type Msg =
  | { type: "DRAFT_CHANGED"; draft: string }
  | { type: "SUBMIT" }
  | { type: "GO_DEEPER" }
  | { type: "GO_BACK" }
  | { type: "SELECTION_CHANGED"; anchor: Anchor | null }
  | { type: "MARK_CLICKED"; thread: ThreadId }
  | { type: "LEARNING_MSG"; msg: LearningMsg }
  | { type: "SAMPLE_CHANGED"; id: string }
  | { type: "CHILD_MSG"; msg: ThreadPaneMsg };

const appClass = cls("app");
const transcriptClass = cls("transcript");
const messageClass = cls("message");
const roleClass = cls("role");
const composerClass = cls("composer");
const paneClass = cls("pane");
const navClass = cls("nav");
const depthClass = cls("depth");
const markClass = cls("mark");
const textClass = cls("text");
const threadPaneClass = cls("thread-pane");
const threadActionClass = cls("thread-action");
const bodyClass = cls("body");
const originQuoteClass = cls("origin-quote");
const sampleClass = cls("sample");
const spacerClass = cls("spacer");

mountStyle(`
.${appClass} {
  font-family: system-ui, sans-serif;
  height: 100%;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.${bodyClass} {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  width: 100%;
  max-width: 44rem;
  margin: 0 auto;
  padding: 1rem 1rem 5rem;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 1rem 2rem;
  align-items: start;
}
.${appClass}[data-split="true"] .${bodyClass} {
  max-width: 88rem;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}
.${paneClass} {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  min-width: 0;
}
.${navClass} {
  flex: none;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.6rem 1rem;
  border-bottom: 1px solid rgba(0, 0, 0, 0.12);
  background: #fff;
}
.${navClass} button {
  font: inherit;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  border: 1px solid rgba(0, 0, 0, 0.15);
  background: #fff;
  cursor: pointer;
}
.${navClass} button:disabled {
  opacity: 0.4;
  cursor: default;
}
.${sampleClass} {
  font: inherit;
}
.${spacerClass} {
  flex: 1;
}
.${depthClass} {
  font-size: 0.75rem;
  opacity: 0.6;
}
.${markClass} {
  border-radius: 2px;
}
.${markClass}[data-live="true"] {
  background: #cfe3ff;
}
.${markClass}[data-mark] {
  background: #ffe8a3;
  cursor: pointer;
}
.${markClass}[data-mark][data-active="true"] {
  background: #ffcf4d;
  box-shadow: 0 0 0 1px #b8860b;
}
.${transcriptClass} {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.${messageClass} {
  white-space: pre-wrap;
  line-height: 1.5;
}
.${messageClass}[data-role="user"] {
  background: rgba(0, 0, 0, 0.05);
  border-radius: 0.5rem;
  padding: 0.5rem 0.75rem;
}
.${roleClass} {
  display: block;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.6;
}
.${composerClass} {
  display: flex;
  gap: 0.5rem;
}
.${threadPaneClass} {
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  border-left: 1px solid rgba(0, 0, 0, 0.1);
  padding-left: 1.5rem;
}
.${originQuoteClass} {
  white-space: pre-wrap;
  border-left: 3px solid #f0b429;
  margin: 0.4rem 0 0;
  padding-left: 0.75rem;
  max-height: 8rem;
  overflow-y: auto;
  font-size: 0.9rem;
  opacity: 0.8;
}
.${threadActionClass} {
  white-space: pre-wrap;
  font-weight: 600;
  font-size: 0.95rem;
}
.${composerClass} textarea {
  flex: 1;
  font: inherit;
  padding: 0.5rem;
  resize: vertical;
}
`);

type SegmentState = {
  text: string;
  /** The thread this run opens; null for plain text and the live selection. */
  thread: ThreadId | null;
  live: boolean;
  active: boolean;
};

type SegmentMsg = { type: "CLICKED"; thread: ThreadId };

/** One run of a message's text: plain, a committed mark, or the live selection.
 * A span rather than a <mark> so all three share one element and bindList can
 * reconcile them without remounting. */
class SegmentView implements View<SegmentState, SegmentMsg> {
  container: HTMLElement;
  private b: Binder<SegmentState>;
  private current: SegmentState;

  constructor(
    container: HTMLElement,
    dispatch: (msg: SegmentMsg) => void,
    initial: SegmentState,
  ) {
    const textRef = ref("segment");
    container.innerHTML = sanitize`<span data-ref="${textRef}"></span>`;
    this.container = container;
    this.current = initial;
    this.b = new Binder(container, initial);
    container.addEventListener("click", () => {
      const thread = this.current.thread;
      if (thread) dispatch({ type: "CLICKED", thread });
    });
    this.b.bindClass(container, (s) => (s.thread || s.live ? markClass : ""));
    this.b.bindContainerAttr("data-mark", (s) => s.thread ?? undefined);
    this.b.bindContainerAttr("data-live", (s) => (s.live ? "true" : undefined));
    this.b.bindContainerAttr("data-active", (s) =>
      s.active ? "true" : undefined,
    );
    this.b.bindText(textRef, (s) => s.text);
  }

  sync(state: SegmentState): void {
    this.current = state;
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

type MessageState = {
  message: Message;
  segments: ReadonlyArray<Segment>;
  active: ThreadId | null;
};

class MessageView implements View<MessageState, SegmentMsg> {
  container: HTMLElement;
  private b: Binder<MessageState>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: SegmentMsg) => void,
    initial: MessageState,
  ) {
    const roleRef = ref("role");
    const textRef = ref("text");
    container.className = messageClass;
    container.innerHTML = sanitize`
      <span class="${roleClass}" data-ref="${roleRef}"></span>
      <span class="${textClass}" data-ref="${textRef}"></span>
    `;
    this.container = container;
    this.b = new Binder(container, initial);
    this.b.bindText(roleRef, (s) => s.message.role);
    // Keyed by start offset: the transcript is append-only, so a run keeps its
    // start while the message grows and while marks are added after it.
    this.b.bindList(textRef, "span", (s) =>
      s.segments.map((seg) =>
        showKeyed(
          String(seg.start),
          SegmentView,
          {
            text: s.message.text.slice(seg.start, seg.end),
            thread: seg.thread,
            live: seg.live,
